changeSet.sql:
CREATE TABLE finances.holding_types ( id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, external_id UUID NOT NULL DEFAULT gen_random_uuid() UNIQUE, name TEXT NOT NULL, kinds finances.wallet_kind[] NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), CONSTRAINT holding_types_name_key UNIQUE (name), CONSTRAINT holding_types_kinds_not_empty CHECK (cardinality(kinds) > 0) );
INSERT INTO finances.holding_types (external_id, name, kinds, created_at) SELECT stock_types.external_id, stock_types.name, '{STOCKS}', stock_types.created_at FROM finances.stock_types;
INSERT INTO finances.holding_types (external_id, name, kinds, created_at) SELECT fund_types.external_id, CASE WHEN EXISTS (SELECT 1 FROM finances.stock_types WHERE stock_types.name = fund_types.name) THEN fund_types.name || ' (fundo)' ELSE fund_types.name END, '{FUNDS}', fund_types.created_at FROM finances.fund_types;
INSERT INTO finances.holding_types (name, kinds) VALUES ('Cripto', '{CRYPTO}');

ALTER TABLE finances.stock_holdings
    ADD COLUMN holding_type_id BIGINT REFERENCES finances.holding_types(id) ON DELETE RESTRICT;
ALTER TABLE finances.fund_holdings
    ADD COLUMN holding_type_id BIGINT REFERENCES finances.holding_types(id) ON DELETE RESTRICT;
ALTER TABLE finances.crypto_holdings
    ADD COLUMN holding_type_id BIGINT REFERENCES finances.holding_types(id) ON DELETE RESTRICT;

UPDATE finances.stock_holdings
SET holding_type_id = holding_types.id
FROM finances.stock_types
JOIN finances.holding_types ON holding_types.external_id = stock_types.external_id
WHERE stock_types.id = stock_holdings.stock_type_id;

UPDATE finances.fund_holdings
SET holding_type_id = holding_types.id
FROM finances.fund_types
JOIN finances.holding_types ON holding_types.external_id = fund_types.external_id
WHERE fund_types.id = fund_holdings.fund_type_id;

UPDATE finances.crypto_holdings
SET holding_type_id = (SELECT id FROM finances.holding_types WHERE name = 'Cripto');

ALTER TABLE finances.stock_holdings ALTER COLUMN holding_type_id SET NOT NULL;
ALTER TABLE finances.fund_holdings ALTER COLUMN holding_type_id SET NOT NULL;

CREATE INDEX idx_stock_holdings_holding_type_id ON finances.stock_holdings (holding_type_id);
CREATE INDEX idx_fund_holdings_holding_type_id ON finances.fund_holdings (holding_type_id);
CREATE INDEX idx_crypto_holdings_holding_type_id ON finances.crypto_holdings (holding_type_id);

rollback.sql:
ALTER TABLE finances.stock_holdings DROP COLUMN holding_type_id;
ALTER TABLE finances.fund_holdings DROP COLUMN holding_type_id;
ALTER TABLE finances.crypto_holdings DROP COLUMN holding_type_id;

