CREATE TABLE finances.stock_types (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    external_id UUID NOT NULL DEFAULT gen_random_uuid() UNIQUE,
    name TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT stock_types_name_key UNIQUE (name)
);

CREATE TABLE finances.fund_types (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    external_id UUID NOT NULL DEFAULT gen_random_uuid() UNIQUE,
    name TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT fund_types_name_key UNIQUE (name)
);

INSERT INTO finances.stock_types (external_id, name, created_at)
SELECT external_id, name, created_at
FROM finances.holding_types
WHERE 'STOCKS' = ANY (kinds);

INSERT INTO finances.fund_types (external_id, name, created_at)
SELECT external_id, regexp_replace(name, ' \(fundo\)$', ''), created_at
FROM finances.holding_types
WHERE 'FUNDS' = ANY (kinds);

ALTER TABLE finances.stock_holdings
    ADD COLUMN stock_type_id BIGINT REFERENCES finances.stock_types(id) ON DELETE RESTRICT;
ALTER TABLE finances.fund_holdings
    ADD COLUMN fund_type_id BIGINT REFERENCES finances.fund_types(id) ON DELETE RESTRICT;

UPDATE finances.stock_holdings
SET stock_type_id = stock_types.id
FROM finances.holding_types
JOIN finances.stock_types ON stock_types.external_id = holding_types.external_id
WHERE holding_types.id = stock_holdings.holding_type_id;

UPDATE finances.fund_holdings
SET fund_type_id = fund_types.id
FROM finances.holding_types
JOIN finances.fund_types ON fund_types.external_id = holding_types.external_id
WHERE holding_types.id = fund_holdings.holding_type_id;

ALTER TABLE finances.stock_holdings ALTER COLUMN stock_type_id SET NOT NULL;
ALTER TABLE finances.fund_holdings ALTER COLUMN fund_type_id SET NOT NULL;

CREATE INDEX idx_stock_holdings_stock_type_id ON finances.stock_holdings (stock_type_id);
CREATE INDEX idx_fund_holdings_fund_type_id ON finances.fund_holdings (fund_type_id);
